-- Clinic: synthetic sample data for the dhimantAI "Ask your data" lab.
-- Generated by scripts/datalab/generate_seeds.py. Do not edit by hand.
-- Every name and number is invented. No real person, shop, school or clinic.

CREATE TABLE doctors (
  doctor_id integer PRIMARY KEY,
  doctor_name text NOT NULL,
  speciality text NOT NULL,
  clinic_days text NOT NULL
);
COMMENT ON TABLE doctors IS 'One row per doctor (invented names).';
COMMENT ON COLUMN doctors.doctor_id IS 'Doctor number.';
COMMENT ON COLUMN doctors.doctor_name IS 'Invented name.';
COMMENT ON COLUMN doctors.speciality IS 'Speciality.';
COMMENT ON COLUMN doctors.clinic_days IS 'Days of the week the doctor sees patients here. One doctor comes only twice a week.';

CREATE TABLE appointments (
  appointment_id integer PRIMARY KEY,
  patient_code text NOT NULL,
  doctor_id integer NOT NULL REFERENCES doctors,
  visit_date date NOT NULL,
  visit_type text NOT NULL,
  booked_time time,
  arrived_time time,
  seen_time time,
  status text NOT NULL,
  wait_minutes integer
);
COMMENT ON TABLE appointments IS 'One row per appointment or walk-in visit.';
COMMENT ON COLUMN appointments.appointment_id IS 'Row number.';
COMMENT ON COLUMN appointments.patient_code IS 'Invented patient code; the same code means the same patient.';
COMMENT ON COLUMN appointments.doctor_id IS 'Doctor (see doctors).';
COMMENT ON COLUMN appointments.visit_date IS 'Day of the visit.';
COMMENT ON COLUMN appointments.visit_type IS 'booked (appointment made earlier) or walk_in (no appointment).';
COMMENT ON COLUMN appointments.booked_time IS 'Appointment time. Blank for walk-ins.';
COMMENT ON COLUMN appointments.arrived_time IS 'Time reception marked the patient as arrived. Blank if the patient never came.';
COMMENT ON COLUMN appointments.seen_time IS 'Time the doctor called the patient in. Blank if the patient was not seen.';
COMMENT ON COLUMN appointments.status IS 'seen, cancelled (by the patient, in advance) or no_show (booked but never came).';
COMMENT ON COLUMN appointments.wait_minutes IS 'Minutes from arrival to being seen. Blank unless the patient was seen. It is not how late the doctor ran: early arrivals wait longer.';
